<?php use Namira\{Security,Permissions,CommunityUI as UI}; ?>
<?php if(Namira\MemberSchema::ready($db)&&$editing&&Permissions::allows($db,$user,$tab==='contributions'?'contributions.review':'submissions.review')):
$choices=$tab==='contributions'?['submitted'=>['reviewing','needs_changes','rejected'],'reviewing'=>['approved','partial_approved','needs_changes','rejected'],'approved'=>['reviewing'],'partial_approved'=>['reviewing']]:['submitted'=>['reviewing','needs_changes','rejected'],'reviewing'=>['approved','needs_changes','rejected'],'approved'=>['reviewing','rejected']];
$sender=Namira\Db::query($db,'SELECT p.display_name,i.mobile,i.mobile_verified_at FROM account_profiles p LEFT JOIN account_identities i ON i.user_id=p.user_id WHERE p.user_id=?',[$editing['user_id']])->fetch(); ?>
<section class="panel"><p>ارسال‌کننده: <?= e($sender['display_name']??'حساب قدیمی') ?> · موبایل تأییدشده: <span dir="ltr"><?= e(!empty($sender['mobile_verified_at'])?$sender['mobile']:'تأیید نشده') ?></span></p><p>نسبت اعلام‌شده، ادعای ارسال‌کننده است و احراز هویت خانوادگی محسوب نمی‌شود.</p></section>
<?php if(!empty($choices[$editing['status']])): ?><form class="panel community-form" method="post"><?= Security::field() ?><input type="hidden" name="action" value="<?= $tab==='contributions'?'contribution-review':'submission-review' ?>"><input type="hidden" name="id" value="<?= (int)$editing['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$editing['revision'] ?>"><h3>بررسی و ثبت تصمیم</h3><label>تصمیم<select name="status"><?php foreach($choices[$editing['status']] as $s): ?><option value="<?= e($s) ?>"><?= e(UI::state($s)) ?></option><?php endforeach ?></select></label><label>شناسه پرونده مقصد<input type="number" name="martyr_id" value="<?= (int)$editing['martyr_id']?:'' ?>" min="1"></label>
<?php if($tab==='submissions'): ?><label>شناسه هنرمند<input type="number" name="artist_id" min="1" value="<?= (int)$editing['artist_id']?:'' ?>"></label><label>شرایط استفاده تأییدشده<textarea name="reviewed_rights" maxlength="5000"><?= e($editing['data']['rights_text']??'') ?></textarea></label><label>نقش پدیدآورنده<input name="creator_role" value="پدیدآورنده" maxlength="100"></label><label class="check"><input type="checkbox" name="identity_ack" value="1">انتساب اثر به شهید و هنرمند را بررسی کرده‌ام.</label><label class="check"><input type="checkbox" name="allow_download" value="1">دانلود اصل در محدوده رضایت صاحب اثر مجاز باشد.</label><?php endif ?>
<label>توضیح نتیجه؛ برای ارسال‌کننده قابل نمایش است<textarea name="note" required maxlength="5000" rows="3"></textarea></label><button class="primary">ثبت تصمیم بررسی</button></form><?php endif ?><?php endif ?>
